<?php
require_once '../includes/auth.php';
require_once '../includes/db.php';
require_once '../includes/booking_invoice_helper.php';
require_once '../includes/staff_ledger_helper.php';
require_once '../includes/header.php';
require_once '../includes/navbar.php';
require_once '../includes/sidebar.php';

$user_id=(int)$_SESSION['user_id']; ensure_booking_invoice_table($conn); ensure_booking_invoice_type_table($conn,$user_id); ensure_staff_ledger_table($conn);
$month=isset($_GET['month'])?(int)$_GET['month']:(int)date('m'); $year=isset($_GET['year'])?(int)$_GET['year']:(int)date('Y');
if($month<1||$month>12)$month=(int)date('m'); if($year<2020||$year>2100)$year=(int)date('Y');
function report_scalar($conn,$sql,$types,$values){$stmt=mysqli_prepare($conn,$sql); if(!$stmt)return 0.0; mysqli_stmt_bind_param($stmt,$types,...$values); mysqli_stmt_execute($stmt); $row=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); return (float)($row['amount']??0);}
function report_expense_sql($date_sql){return "SELECT COALESCE(SUM(amount),0) amount FROM (SELECT e.amount FROM expenses e WHERE e.user_id=? AND e.approval_status='approved' {$date_sql('e.txn_date')} UNION ALL SELECT l.amount FROM staff_ledger_entries l WHERE l.user_id=? {$date_sql('l.entry_date')}) expense_rows";}
$sales_sql="SELECT COALESCE(SUM(bi.amount),0) amount FROM booking_invoices bi LEFT JOIN booking_invoice_types bit ON bit.user_id=bi.user_id AND bit.type_key=bi.invoice_type WHERE bi.user_id=? AND bi.status='confirmed' AND COALESCE(bit.behavior,'income')='income' AND MONTH(bi.invoice_date)=? AND YEAR(bi.invoice_date)=?";
$total_sales=report_scalar($conn,$sales_sql,'iii',[$user_id,$month,$year]);
$expense_sql="SELECT COALESCE(SUM(amount),0) amount FROM (SELECT e.amount FROM expenses e WHERE e.user_id=? AND e.approval_status='approved' AND MONTH(e.txn_date)=? AND YEAR(e.txn_date)=? UNION ALL SELECT l.amount FROM staff_ledger_entries l WHERE l.user_id=? AND MONTH(l.entry_date)=? AND YEAR(l.entry_date)=?) x";
$total_expenses=report_scalar($conn,$expense_sql,'iiiiii',[$user_id,$month,$year,$user_id,$month,$year]); $net_profit=$total_sales-$total_expenses;

$breakdown_sql="SELECT category_name,SUM(amount) amount FROM (SELECT CONVERT(CONCAT('Expense: ',COALESCE(c.category_name,'General')) USING utf8mb4) COLLATE utf8mb4_unicode_ci category_name,e.amount FROM expenses e LEFT JOIN categories c ON c.id=e.category_id WHERE e.user_id=? AND e.approval_status='approved' AND MONTH(e.txn_date)=? AND YEAR(e.txn_date)=? UNION ALL SELECT CONVERT(CONCAT('Staff ',UPPER(LEFT(l.entry_type,1)),SUBSTRING(l.entry_type,2)) USING utf8mb4) COLLATE utf8mb4_unicode_ci category_name,l.amount FROM staff_ledger_entries l WHERE l.user_id=? AND MONTH(l.entry_date)=? AND YEAR(l.entry_date)=?) x GROUP BY category_name ORDER BY amount DESC,category_name";
$stmt=mysqli_prepare($conn,$breakdown_sql); mysqli_stmt_bind_param($stmt,'iiiiii',$user_id,$month,$year,$user_id,$month,$year); mysqli_stmt_execute($stmt); $result=mysqli_stmt_get_result($stmt); $breakdown=[]; while($row=mysqli_fetch_assoc($result))$breakdown[]=$row;

$month_labels=[];$month_sales=[];$month_expenses=[];for($m=1;$m<=12;$m++){ $month_labels[]=date('M',mktime(0,0,0,$m,1));$month_sales[$m]=0.0;$month_expenses[$m]=0.0; }
$stmt=mysqli_prepare($conn,"SELECT MONTH(bi.invoice_date) m,SUM(bi.amount) amount FROM booking_invoices bi LEFT JOIN booking_invoice_types bit ON bit.user_id=bi.user_id AND bit.type_key=bi.invoice_type WHERE bi.user_id=? AND bi.status='confirmed' AND COALESCE(bit.behavior,'income')='income' AND YEAR(bi.invoice_date)=? GROUP BY MONTH(bi.invoice_date)"); mysqli_stmt_bind_param($stmt,'ii',$user_id,$year);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($result))$month_sales[(int)$row['m']]=(float)$row['amount'];
$stmt=mysqli_prepare($conn,"SELECT m,SUM(amount) amount FROM (SELECT MONTH(e.txn_date) m,e.amount FROM expenses e WHERE e.user_id=? AND e.approval_status='approved' AND YEAR(e.txn_date)=? UNION ALL SELECT MONTH(l.entry_date) m,l.amount FROM staff_ledger_entries l WHERE l.user_id=? AND YEAR(l.entry_date)=?) x GROUP BY m");mysqli_stmt_bind_param($stmt,'iiii',$user_id,$year,$user_id,$year);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($result))$month_expenses[(int)$row['m']]=(float)$row['amount'];

$start_year=$year-4;$year_labels=[];$year_sales=[];$year_expenses=[];for($y=$start_year;$y<=$year;$y++){ $year_labels[]=(string)$y;$year_sales[$y]=0.0;$year_expenses[$y]=0.0; }
$stmt=mysqli_prepare($conn,"SELECT YEAR(bi.invoice_date) y,SUM(bi.amount) amount FROM booking_invoices bi LEFT JOIN booking_invoice_types bit ON bit.user_id=bi.user_id AND bit.type_key=bi.invoice_type WHERE bi.user_id=? AND bi.status='confirmed' AND COALESCE(bit.behavior,'income')='income' AND YEAR(bi.invoice_date) BETWEEN ? AND ? GROUP BY YEAR(bi.invoice_date)");mysqli_stmt_bind_param($stmt,'iii',$user_id,$start_year,$year);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($result))$year_sales[(int)$row['y']]=(float)$row['amount'];
$stmt=mysqli_prepare($conn,"SELECT y,SUM(amount) amount FROM (SELECT YEAR(e.txn_date) y,e.amount FROM expenses e WHERE e.user_id=? AND e.approval_status='approved' AND YEAR(e.txn_date) BETWEEN ? AND ? UNION ALL SELECT YEAR(l.entry_date) y,l.amount FROM staff_ledger_entries l WHERE l.user_id=? AND YEAR(l.entry_date) BETWEEN ? AND ?) x GROUP BY y");mysqli_stmt_bind_param($stmt,'iiiiii',$user_id,$start_year,$year,$user_id,$start_year,$year);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($result))$year_expenses[(int)$row['y']]=(float)$row['amount'];
?>
