<div class="row"><div class="col-md-4"><div class="small-box bg-primary"><div class="inner"><h3>BDT <?=number_format($total_sales,2)?></h3><p>Total Sales</p></div><div class="icon"><i class="fas fa-chart-line"></i></div></div></div><div class="col-md-4"><div class="small-box bg-danger"><div class="inner"><h3>BDT <?=number_format($total_expenses,2)?></h3><p>Total Expenses</p></div><div class="icon"><i class="fas fa-receipt"></i></div></div></div><div class="col-md-4"><div class="small-box bg-<?=$net_profit>=0?'success':'warning'?>"><div class="inner"><h3>BDT <?=number_format($net_profit,2)?></h3><p>Net Profit</p></div><div class="icon"><i class="fas fa-wallet"></i></div></div></div></div>
<div class="row"><div class="col-md-6"><div class="card"><div class="card-header"><h3 class="card-title">Monthly Sales vs Expense — <?=$year?></h3></div><div class="card-body"><div style="height:330px"><canvas id="monthlyChart"></canvas></div></div></div></div><div class="col-md-6"><div class="card"><div class="card-header"><h3 class="card-title">Yearly Sales vs Expense</h3></div><div class="card-body"><div style="height:330px"><canvas id="yearlyChart"></canvas></div></div></div></div></div>
<div class="row"><div class="col-md-6"><div class="card"><div class="card-header"><h3 class="card-title">Profit Calculation</h3></div><div class="card-body p-0"><table class="table table-bordered mb-0"><tbody><tr><th>Total Sales</th><td class="text-right">BDT <?=number_format($total_sales,2)?></td></tr><tr><th>Less: Total Expenses</th><td class="text-right text-danger">− BDT <?=number_format($total_expenses,2)?></td></tr><tr class="<?=$net_profit>=0?'table-success':'table-danger'?>"><th>Net Profit</th><th class="text-right">BDT <?=number_format($net_profit,2)?></th></tr></tbody></table></div></div></div><div class="col-md-6"><div class="card"><div class="card-header"><h3 class="card-title">Expense Breakdown</h3></div><div class="card-body p-0"><table class="table table-bordered mb-0"><thead><tr><th>Category</th><th class="text-right">Amount</th></tr></thead><tbody><?php foreach($breakdown as $item){?><tr><td><?=htmlspecialchars($item['category_name'])?></td><td class="text-right">BDT <?=number_format($item['amount'],2)?></td></tr><?php }if(empty($breakdown)){?><tr><td colspan="2" class="text-center text-muted">No expenses for this month.</td></tr><?php }?></tbody><tfoot><tr><th>Total Expenses</th><th class="text-right">BDT <?=number_format($total_expenses,2)?></th></tr></tfoot></table></div></div></div></div>
</div></section>
<?php $page_script='<script>var chartOptions={responsive:true,maintainAspectRatio:false,scales:{yAxes:[{ticks:{beginAtZero:true}}]}};new Chart(document.getElementById("monthlyChart"),{type:"bar",data:{labels:'.json_encode($month_labels).',datasets:[{label:"Sales",data:'.json_encode(array_values($month_sales)).',backgroundColor:"#1677e8"},{label:"Expense",data:'.json_encode(array_values($month_expenses)).',backgroundColor:"#dc3545"}]},options:chartOptions});new Chart(document.getElementById("yearlyChart"),{type:"bar",data:{labels:'.json_encode($year_labels).',datasets:[{label:"Sales",data:'.json_encode(array_values($year_sales)).',backgroundColor:"#28a745"},{label:"Expense",data:'.json_encode(array_values($year_expenses)).',backgroundColor:"#ffc107"}]},options:chartOptions});</script><style>@page{size:A4 landscape;margin:10mm}@media print{html,body{background:#fff!important;color:#14213d!important;font-size:10px!important}.main-header,.main-sidebar,.main-footer,.card:first-child,.btn{display:none!important}.content-wrapper,.content,.container-fluid{margin:0!important;padding:0!important;width:100%!important;min-height:0!important}.report-print-heading{display:block!important;border-bottom:2px solid #1677e8!important;padding:0 0 10px!important;margin:0 0 12px!important;text-align:center!important}.report-print-heading h2{font-size:20px!important;letter-spacing:1px!important;margin:0 0 4px!important;color:#0b2e59!important}.report-print-heading strong{font-size:11px!important;color:#5d6b82!important}.row{display:flex!important;flex-wrap:wrap!important;margin:0 -4px!important}.row>.col-md-4{flex:0 0 33.333%!important;max-width:33.333%!important;padding:0 4px!important}.row>.col-md-6{flex:0 0 50%!important;max-width:50%!important;padding:0 4px!important}.card{box-shadow:none!important;border:1px solid #d9e2ef!important;border-radius:0!important;margin-bottom:8px!important;break-inside:avoid!important}.card-header{background:#f3f7fc!important;border-bottom:1px solid #d9e2ef!important;padding:7px 10px!important;font-weight:700!important}.card-body{padding:8px!important}.small-box{background:#fff!important;border:1px solid #d9e2ef!important;box-shadow:none!important;min-height:auto!important;margin-bottom:8px!important;color:#14213d!important}.small-box h3,.small-box p{color:#14213d!important}.small-box h3{font-size:17px!important;margin:0!important}.small-box p{font-size:10px!important;margin:3px 0 0!important}.small-box .icon{display:none!important}canvas{max-height:150px!important}table{width:100%!important;font-size:9px!important;border-collapse:collapse!important}th{background:#eaf2fb!important;color:#12375d!important}th,td{padding:5px!important;border:1px solid #d9e2ef!important}.bg-success,.bg-danger,.bg-warning{background:#fff!important;color:#14213d!important}}</style>';require_once '../includes/footer.php';?>
